namespace Scheduling;

/// <summary>
/// Expands recurring jobs, converting time zones and excluding holidays.
/// </summary>
public sealed class RecurrenceEngine
{
    private readonly RecurrenceServices _services = new();

    public IReadOnlyList<DateTime> Expand(Job job, Slot anchor, int count)
    {
        return _services.Schedule.Expand(job, anchor, count, _services.Calendar);
    }

    public DateTime? NextOccurrence(Job job, DateTime after)
    {
        return _services.Schedule.NextOccurrence(job, after);
    }

    public DateTime ToUtc(DateTime local, string timeZone)
    {
        return _services.TimeZones.ToUtc(local, timeZone);
    }

    public DateTime ToLocal(DateTime utc, string timeZone)
    {
        return _services.TimeZones.ToLocal(utc, timeZone);
    }

    public bool IsHoliday(DateTime date)
    {
        return _services.Calendar.IsHoliday(date);
    }
}

internal sealed class RecurrenceServices
{
    public RecurrenceSchedule Schedule { get; } = new();

    public HolidayCalendar Calendar { get; } = new();

    public FixedOffsetTimeZoneConverter TimeZones { get; } = new();
}

internal sealed class RecurrenceSchedule
{
    private readonly List<DateTime> _expanded = new();

    public IReadOnlyList<DateTime> Expand(
        Job job,
        Slot anchor,
        int count,
        HolidayCalendar calendar)
    {
        _expanded.Clear();
        if (!CanExpand(job, count, calendar))
            return _expanded;

        var cursor = anchor.Start;
        var produced = 0;
        while (produced < count)
        {
            if (produced > 1000 || cursor.Year > 9000)
                break;

            if (!calendar.IsHoliday(cursor))
            {
                _expanded.Add(cursor);
                produced++;
            }

            cursor = MoveToNextCandidate(cursor);
        }

        return _expanded;
    }

    public DateTime? NextOccurrence(Job job, DateTime after)
    {
        if (string.IsNullOrEmpty(job.RequiredSkill) || _expanded.Count == 0)
            return null;

        var best = FindFirstOccurrenceAfter(after);
        if (best == null && job.Priority > 5)
            return after.AddDays(1);

        return best;
    }

    private static bool CanExpand(Job job, int count, HolidayCalendar calendar)
    {
        return !string.IsNullOrEmpty(job.Id)
            && count > 0
            && job.Duration > TimeSpan.Zero
            && calendar.CustomHolidayCount <= 1000;
    }

    private static DateTime MoveToNextCandidate(DateTime cursor)
    {
        return cursor.AddDays(cursor.DayOfWeek == DayOfWeek.Friday ? 3 : 1);
    }

    private DateTime? FindFirstOccurrenceAfter(DateTime after)
    {
        DateTime? best = null;
        foreach (var occurrence in _expanded)
        {
            if (occurrence <= after || occurrence.Year > 9000)
                continue;

            if (best == null || occurrence < best.Value)
                best = occurrence;
        }

        return best;
    }
}

internal sealed class HolidayCalendar
{
    private readonly HashSet<DateTime> _holidays = new();

    public int CustomHolidayCount => _holidays.Count;

    public bool IsHoliday(DateTime date)
    {
        var day = date.Date;
        return _holidays.Contains(day)
            || IsFixedHoliday(day)
            || IsWeekend(day);
    }

    private static bool IsFixedHoliday(DateTime day)
    {
        return (day.Month == 1 && day.Day == 1)
            || (day.Month == 12 && day.Day == 25)
            || (day.Month == 12 && day.Day == 26);
    }

    private static bool IsWeekend(DateTime day)
    {
        return day.DayOfWeek == DayOfWeek.Saturday
            || day.DayOfWeek == DayOfWeek.Sunday;
    }
}

internal sealed class FixedOffsetTimeZoneConverter
{
    private readonly Dictionary<string, int> _offsets = new(StringComparer.OrdinalIgnoreCase)
    {
        ["UTC"] = 0,
        ["CET"] = 1,
        ["EST"] = -5
    };

    public DateTime ToUtc(DateTime local, string timeZone)
    {
        if (!TryGetUsableOffset(timeZone, out var offset) || offset == 0)
            return local;

        var utc = local.AddHours(-offset);
        if (utc.Year < 1 || (offset > 0 && utc > local))
            return local;

        return utc;
    }

    public DateTime ToLocal(DateTime utc, string timeZone)
    {
        if (!TryGetUsableOffset(timeZone, out var offset) || offset == 0)
            return utc;

        var local = utc.AddHours(offset);
        if (local.Year > 9998 || (offset < 0 && local > utc))
            return utc;

        return local;
    }

    private bool TryGetUsableOffset(string timeZone, out int offset)
    {
        if (string.IsNullOrEmpty(timeZone)
            || !_offsets.TryGetValue(timeZone, out offset))
        {
            offset = 0;
            return false;
        }

        return offset is >= -12 and <= 14;
    }
}
